# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: emit
def emit(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs) - 1, 'tally': sorted(d.items())}

# region: digest
def digest(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(sift(emit(fold(gather(intake(raw))))))

